SELECT title, content, version, task_id
FROM ontology_analysis_memory
WHERE status = #{status} AND task_id = #{taskId}
ORDER BY update_time DESC, memory_id DESC
LIMIT #{limit}

SELECT title, content, version, task_id
FROM ontology_analysis_memory
WHERE status = #{status} AND space_id = #{spaceId}
ORDER BY update_time DESC, memory_id DESC
LIMIT #{limit}
